include "qelib1.inc";     // Including the standard quantum library [^2]

// Quantum gate application
qreg qubits[2];           // Declaring a quantum register with two qubits [^3]
cx qubits[0], qubits[1];  // Applying a CNOT gate to the qubits [^4]

// Commenting out a segment of code can be accomplished
// by using consecutive single-line comments like these.
// This approach is common for debugging or to explain
// a sequence of instructions in detail.

// PhotonQ Experiment: Version String Declaration [^5]
OPENQASM 2.0;             // Correctly specifies OpenQASM version [^1]
include "qelib1.inc";     // Including the standard library for convenience [^2]

// Quantum gate application
qreg qubits[2];           // Declaring a quantum register with two qubits [^3]
