OPENQASM 2.0;           // Declares the version of OpenQASM [^1]
include "qelib1.inc";   // Brings in the standard gate definitions [^2]

// Quantum register declaration
qreg qubits[2]; // Defines a quantum register with two qubits [^3]

// Quantum gate application
h qubits[0]; // Applies a Hadamard gate to the first qubit [^4]

OPENQASM 2.0; // Declaration of OpenQASM version [^1]
include "qelib1.inc"; // Inclusion of the standard library [^2]

// Single-qubit register declaration
qreg qubit[1]; // A quantum register representing a single qubit [^3]

// Hadamard gate applied to the single qubit
h qubit[0]; // Enacting a Hadamard transformation [^4]

OPENQASM 2.0;                 // Specify OpenQASM version [^1]
include "qelib1.inc";         // Include the standard quantum library [^2]

// Quantum register with a single qubit and classical register with two bits
qreg qubit[1];                // Single-qubit quantum register [^4]
creg bits[2];                 // Two-bit classical register [^3]

// Prepare qubit in a superposition state
h qubit[0];                   // Apply Hadamard gate to the qubit [^5]

// Measure the qubit and store the result in the first bit of classical register
measure qubit[0] -> bits[0];  // Measurement operation [^6]

// The second bit remains in its initial state (0)

OPENQASM 2.0;                 // Define the OpenQASM version [^1]
include "qelib1.inc";         // Include the standard quantum library [^2]

// Declare a quantum register
qreg qubits[1];               // Single-qubit quantum register [^3]

// Place the first qubit in a superposition state
h qubits[0];                  // Apply Hadamard gate [^4]

// Return the first qubit to its initial state
reset qubits[0];              // Reset operation

OPENQASM 2.0;                 // Define the OpenQASM version [^1]
include "qelib1.inc";         // Include the standard quantum library [^2]

// Declare a quantum register with multiple qubits
qreg qubits[4]; // Single-qubit quantum register [^3]

// Prepare each qubit in a superposition state
h qubits[0];                  // Apply Hadamard gate to the first qubit [^4]
h qubits[1];                  // Apply Hadamard gate to the second qubit [^4]
h qubits[2];                  // Apply Hadamard gate to the third qubit [^4]
h qubits[3];                  // Apply Hadamard gate to the fourth qubit [^4]

// Reset all qubits in the register to their initial states
reset qubits;
